// Default doc counts - will be overridden by actual data
export const DOC_COUNTS_DEFAULT = [0, 1, 3, 5, 10, 20, 32];

// Helper to generate appropriate doc counts based on data length
export const getDocCountsForLength = (length) => {
  if (length === 2) return [0, 10];
  if (length === 3) return [0, 5, 10];
  if (length === 4) return [0, 3, 5, 10];
  if (length === 5) return [0, 1, 5, 10, 20];
  if (length === 6) return [0, 1, 3, 5, 10, 20];
  if (length === 7) return [0, 1, 3, 5, 10, 20, 32];
  // For any other length, generate evenly spaced values
  if (length <= 1) return [0];
  const result = [];
  for (let i = 0; i < length; i++) {
    result.push(i === 0 ? 0 : i === length - 1 ? 32 : Math.round((32 * i) / (length - 1)));
  }
  return result;
};

